package kotobaya.dict

import kotobaya.server.Database
import kotobaya.server.TestPg
import org.postgresql.PGConnection
import java.io.StringReader
import java.util.zip.GZIPInputStream

/**
 * The T101 loader's output on `fixtures/dict` (2000 entries, 612 kanji), as a committed data-only dump
 * (`dict/ref_fixture.sql.gz`, regenerated by `dict/make_fixture_dump.sh`), loaded into a migrated
 * C.UTF-8 database. The fixture has no frequency lists, so setup ranks the common entries by `seq`.
 */
object DictFixture {
    /** Entries retired in setup (as a dict-refresh would: `retired_release_id` set, forms and glosses dropped). */
    val retired = listOf(1584660L)

    val db: Database by lazy { build() }

    private fun build(): Database {
        val db = TestPg.migratedDb()
        db.dataSource.connection.use { c ->
            val copy = c.unwrap(PGConnection::class.java).copyAPI
            val lines = GZIPInputStream(javaClass.getResourceAsStream("/dict/ref_fixture.sql.gz")!!).bufferedReader().readLines()
            var i = 0
            while (i < lines.size) {
                val line = lines[i++]
                if (line.startsWith("COPY ")) {
                    val data = StringBuilder()
                    while (lines[i] != "\\.") data.append(lines[i++]).append('\n')
                    i++
                    copy.copyIn(line, StringReader(data.toString()))
                } else if (line.isNotBlank() && !line.startsWith("--") && !line.startsWith("\\")) {
                    c.createStatement().use { it.execute(line) }
                }
            }
        }
        db.txBlocking { dsl ->
            dsl.execute(
                "update ref.dict_entry set freq_rank = r.n from " +
                    "(select seq, row_number() over (order by seq) n from ref.dict_entry where is_common) r " +
                    "where ref.dict_entry.seq = r.seq",
            )
            dsl.execute("insert into ref.dict_release (id, version, built_at) values (2, '2026.11.2', now())")
            for (seq in retired) {
                dsl.execute("update ref.dict_entry set retired_release_id = 2 where seq = ?", seq)
                dsl.execute("delete from ref.dict_entry_form where seq = ?", seq)
                dsl.execute("delete from ref.dict_entry_gloss where seq = ?", seq)
            }
        }
        return db
    }
}
